parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "respuesta_usuario": { "type": "string", "description": "Respuesta en lenguaje natural para el cliente" },
    "tools_utilizadas": { "type": "array", "items": { "type": "string" } },
    "requiere_intervencion_humana": { "type": "boolean" },
    "nombre_detectado": { "type": "string", "description": "Nombre del usuario si lo mencionó en este mensaje, string vacío si no lo mencionó" }
  },
  "required": ["respuesta_usuario", "tools_utilizadas", "requiere_intervencion_humana"]
}

parameters.jsCode:
const salida = $input.first().json.output;

let nombreFinal = 'Cliente';
try {
  nombreFinal = salida.nombre_detectado || $('Set · Usuario Recurrente').first().json.memoria_nombre_usuario || 'Cliente';
} catch (e) {
  try {
    nombreFinal = salida.nombre_detectado || $('Set · Usuario Nuevo').first().json.memoria_nombre_usuario || 'Cliente';
  } catch (e2) {
    nombreFinal = salida.nombre_detectado || 'Cliente';
  }
}

return [{
  json: {
    worker_invocado: salida.tools_utilizadas.length > 0
      ? salida.tools_utilizadas.join(' + ')
      : 'Ninguno',
    categoria: salida.requiere_intervencion_humana
      ? 'DUDOSA'
      : (salida.tools_utilizadas.length > 0
        ? salida.tools_utilizadas.join('+')
        : 'CONVERSACIONAL'),
    parametros_enviados: $('Trigger - Petición del cliente').first().json.chatInput,
    respuesta_recibida: salida.respuesta_usuario,
    estado: salida.requiere_intervencion_humana ? 'escalado' : 'success',
    respuesta_usuario: salida.respuesta_usuario,
    requiere_intervencion_humana: salida.requiere_intervencion_humana,
    nombre_usuario_final: nombreFinal
  }
}];

