parameters.jsCode:
let previo = 0;
try {
  previo = $('Set · Usuario Recurrente').first().json.memoria_intercambios;
} catch (e) {
  try {
    previo = $('Set · Usuario Nuevo').first().json.memoria_intercambios;
  } catch (e2) {
    previo = 0;
  }
}
return [{
  json: {
    ...$input.first().json,
    memoria_intercambios: (Number(previo) || 0) + 1
  }
}];

